pw.py.src:
def long_enough(password):
    return len(password) >= 8


def has_digit(password):
    for ch in password:
        if ch.isdigit():
            return True
    return False


def has_capital(password):
    for ch in password:
        if ch.isupper():
            return True
    return False


def problems(password):
    found = []
    if not long_enough(password):
        found.append("use at least 8 characters")
    if not has_digit(password):
        found.append("add a digit")
    if not has_capital(password):
        found.append("add a capital letter")
    return found


def main():
    while True:
        password = input("New password: ")
        found = problems(password)
        if not found:
            print("Strong password. Saved!")
            break
        for message in found:
            print("-", message)


if __name__ == "__main__":
    main()

