    if not scores:
        return 0
    return sum(scores) / len(scores)


def main():
    scores = []
    while True:
        text = input("Score (blank to stop): ")
        if text == "":
            break
        scores.append(int(text))
    print("Average:", average(scores))


if __name__ == "__main__":
    main()

